#!/usr/bin/env bash
# Two fixes to ProcessSupervisor.start(), both aimed at the mystery
# "kiosk-app exited unexpectedly (code=0)" / logs showing only a start
# banner and nothing else:
#
# 1. PYTHONUNBUFFERED=1 forced on the supervised child's environment.
#    Python fully buffers stdout/stderr whenever they are not a real
#    terminal - which they never are here, they're redirected to
#    kiosk-app.log - and that buffer is only flushed on a clean exit.
#    stop()/restart() (and the watchdog, on a real crash) end the child
#    with terminate()/kill(), which does NOT run Python's normal
#    flush-on-exit machinery, so anything printed but not yet flushed was
#    silently lost - exactly matching a log that showed a start banner and
#    then nothing, no matter what actually happened after that.
#
# 2. On Windows, the child is now spawned with
#    creationflags=CREATE_NEW_PROCESS_GROUP. Without it, a subprocess
#    shares its parent's console, and Windows broadcasts Ctrl+C/Ctrl+Break
#    to EVERY process in that console - so stopping the Agent's own
#    foreground "run" session with Ctrl+C (used throughout this whole
#    debugging session) was very likely ALSO silently killing the
#    supervised kiosk-app child at the same moment, independent of
#    anything actually being wrong with it: a clean exit(0), no
#    traceback, nothing logged, because nothing really went wrong - the
#    console signal just hit both processes at once. explicit stop()/
#    restart() are unaffected, since terminate()/kill() operate on the
#    process handle directly, not through console signals.
#
# Verified (1) by reproducing an abrupt terminate() right after buffered
# (non-flushed) output and confirming it now survives; (2) cannot be
# verified in this Linux-only build environment (CREATE_NEW_PROCESS_GROUP
# does not exist outside Windows) - confirmed instead that the code path
# referencing it is only ever reached on os.name == "nt", so this change
# is inert and harmless everywhere else, and that the full
# start/restart/stop lifecycle still passes on Linux with these changes
# in place.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in agent requirements.txt service_files; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

echo "==> Extracting fixed agent/ into this repo"
TMP_EXTRACT="$(mktemp -d)"
base64 -d > "$TMP_EXTRACT/opslab-agent.tar.gz" << 'AGENT_TAR_EOF_MARKER'

AGENT_TAR_EOF_MARKER
tar -xzf "$TMP_EXTRACT/opslab-agent.tar.gz" -C "$TMP_EXTRACT"

if ! grep -q "CREATE_NEW_PROCESS_GROUP" "$TMP_EXTRACT/agent/process_supervisor.py" || \
   ! grep -q "PYTHONUNBUFFERED" "$TMP_EXTRACT/agent/process_supervisor.py"; then
    echo "    ERROR: fix not found in the extracted agent payload!"
    rm -rf "$TMP_EXTRACT"
    exit 1
fi

rm -f agent/config.py.bak
cp -f "$TMP_EXTRACT/agent/"*.py agent/
echo "    Updated agent/*.py in this repo."

echo "==> Rewriting app/static/installers/opslab-agent.tar.gz (served by /install.ps1)"
cp -f "$TMP_EXTRACT/opslab-agent.tar.gz" app/static/installers/opslab-agent.tar.gz
rm -rf "$TMP_EXTRACT"

echo "==> Verifying"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null && echo "    served agent tarball is readable"

echo ""
echo "Done. On Ewan, re-enroll once more to pick this up (same as the earlier"
echo "agent-side fixes):"
echo "    irm https://kiosksys.opslabsystems.cloud/install.ps1 -OutFile install.ps1; .\\install.ps1 -Token <fresh-token> -AdminUrl https://kiosksys.opslabsystems.cloud"
echo ""
echo "IMPORTANT for testing this specific fix: once it is running (as the actual"
echo "Windows SERVICE, not a foreground console session), leave it as a service and"
echo "check the panel/log after a few minutes - do NOT run it via the foreground"
echo "'... service\\opslab_agent_service.py run' + Ctrl+C pattern used throughout"
echo "this session to test it, since that specific pattern is the exact scenario"
echo "fix #2 addresses and Ctrl+C-ing that console may still stop the kiosk app too"
echo "on a machine that has NOT yet picked up this fix from a fresh enrollment."
